function calibratedCommand(left,right){let adjustment=Math.max(-8,Math.min(8,Number(trim)||0)),direction=read('rover_direction',{left:'forward',right:'forward'}),mapping=read('rover_map','left');let l=left,r=right;if(adjustment>0)r=Math.round(r*(1-adjustment*.05));if(adjustment<0)l=Math.round(l*(1+adjustment*.05));let lc=direction.left==='reverse'?-l:l,rc=direction.right==='reverse'?-r:r;return mapping==='right'?{a:rc,b:lc}:{a:lc,b:rc}}
