function arrangeBlocks2D(){
 if(!workspace)return;
 const movable=workspace.getTopBlocks(false).filter(b=>b.isMovable()).map(block=>{let r=block.getBoundingRectangle();return {block,x:r.left,y:r.top,w:r.right-r.left,h:r.bottom-r.top}});
 if(!movable.length)return;
 const fixed=workspace.getTopBlocks(false).filter(b=>!b.isMovable()).map(block=>{let r=block.getBoundingRectangle();return {x:r.left,y:r.top,w:r.right-r.left,h:r.bottom-r.top}});
 const originX=Math.min(...movable.map(b=>b.x)),originY=Math.min(...movable.map(b=>b.y)),gap=24,placed=[...fixed];
 movable.sort((a,b)=>a.y-b.y||a.x-b.x);
 const previousGroup=Blockly.Events.getGroup();if(!previousGroup)Blockly.Events.setGroup(true);workspace.setResizesEnabled(false);
 try{for(const item of movable){
  const tx=originX+(item.x-originX)*.72,ty=originY+(item.y-originY)*.72;
  const xs=[tx],ys=[ty];for(const p of placed){xs.push(p.x+p.w+gap,p.x-item.w-gap);ys.push(p.y+p.h+gap,p.y-item.h-gap)}
  let best=null,bestScore=Infinity;
  for(const x of xs)for(const y of ys){if(x<originX-gap||y<originY-gap)continue;if(placed.some(p=>x<p.x+p.w+gap&&x+item.w+gap>p.x&&y<p.y+p.h+gap&&y+item.h+gap>p.y))continue;
   let score=(x-tx)**2+(y-ty)**2;for(const p of placed){if(p.original){let dx=item.x-p.original.x,dy=item.y-p.original.y;if(Math.abs(dx)>Math.abs(dy)&&dx*(x-p.x)<0)score+=dx*dx*4;if(Math.abs(dy)>=Math.abs(dx)&&dy*(y-p.y)<0)score+=dy*dy*4}}
   if(score<bestScore){bestScore=score;best={x,y}}
  }
  if(!best)best={x:tx,y:Math.max(ty,...placed.map(p=>p.y+p.h+gap))};
  item.block.moveBy(best.x-item.x,best.y-item.y);placed.push({x:best.x,y:best.y,w:item.w,h:item.h,original:item});
 }}finally{workspace.setResizesEnabled(true);if(!previousGroup)Blockly.Events.setGroup(false)}Blockly.svgResize(workspace)
}
