async function execute(block,token,depth=0){if(depth>10)return;while(block&&token===runToken){let f=n=>block.getFieldValue(n);switch(block.type){case 'both_motors':setMotor(Number(f('LD'))*Number(f('LS')),Number(f('RD'))*Number(f('RS')));break;case 'single_motor':{let v=Number(f('DIR'))*Number(f('SPEED'));setMotor(f('SIDE')==='left'?v:sim.left,f('SIDE')==='right'?v:sim.right);break}case 'stop_car':setMotor(0,0);break;case 'wait_car':await sleep(Number(f('SEC'))*1000,token);break;case 'procedures_callnoreturn':{let name=block.getProcedureCall();let def=block.workspace.getAllBlocks(false).find(b=>b.type==='procedures_defnoreturn'&&b.getProcedureDef()?.[0]===name);if(def)await execute(def.getInputTargetBlock('STACK'),token,depth+1);else notify('找不到自訂積木：'+name);break}case 'repeat_car':for(let i=0;i<Number(f('COUNT'))&&token===runToken;i++)await execute(block.getInputTargetBlock('DO'),token,depth+1);break}block=block.getNextBlock()}}
