function timerDraw(){let t=recording?performance.now()-recordingStart:recordingElapsed;let m=Math.floor(t/60000),s=Math.floor(t/1000)%60,cs=Math.floor(t/10)%100;$('#timer').textContent=[m,s].map(v=>String(v).padStart(2,'0')).join(':')+'.'+String(cs).padStart(2,'0')}
