$('#recordConvert').onclick=()=>{if(!recorded.length||!workspace)return;$('#recordNameForm').hidden=false;$('#recordName').value='';$('#recordName').focus()};$('#recordNameCancel').onclick=()=>{$('#recordNameForm').hidden=true};$('#recordNameForm').onsubmit=e=>{e.preventDefault();if(!recorded.length||!workspace)return;let name=$('#recordName').value.trim();if(!name){notify('請輸入功能名稱。');$('#recordName').focus();return}const saved=Blockly.serialization.workspaces.save(workspace);try{let def=workspace.newBlock('procedures_defnoreturn');def.setFieldValue(name,'NAME');def.initSvg();def.render();def.moveBy(40,40);let tail=null;function append(type,fields={},procedureName=null){let b=workspace.newBlock(type);if(procedureName)b.loadExtraState({name:procedureName});for(const [k,v] of Object.entries(fields))b.setFieldValue(String(v),k);b.initSvg();b.render();(tail?tail.nextConnection:def.getInput('STACK').connection).connect(b.previousConnection);tail=b}function wait(ms){let seconds=Math.round(ms/100)/10;while(seconds>0){let chunk=Math.min(seconds,30);append('wait_car',{SEC:chunk});seconds=Math.round((seconds-chunk)*10)/10}}let last=0;for(const r of recorded){let target=workspace.getBlockById(r.functionId);if(!target||target.type!=='procedures_defnoreturn')throw new Error('錄製的功能已刪除，無法建立');if($('#recordKeepGaps').checked)wait(r.start-last);append('procedures_callnoreturn',{},target.getProcedureDef()[0]);last=r.end}let actualName=def.getProcedureDef()[0];$('#recordNameForm').hidden=true;showPage('blocks');Blockly.svgResize(workspace);arrangeBlocks2D();notify('已建立自訂功能「'+actualName+'」。')}catch(e){Blockly.serialization.workspaces.load(saved,workspace);notify(e.message==='錄製的功能已刪除，無法建立'?e.message:'建立失敗，請再試一次。');console.error(e)}};
