let trim=0,trimHistory=[],lastTestChannel=null;const savedMap=read('rover_map',null),wheelMapping=savedMap?{a:savedMap,b:savedMap==='left'?'right':'left'}:{a:null,b:null};function updateWheelMapping(){for(const ch of ['a','b'])$('#map'+ch.toUpperCase()).textContent=wheelMapping[ch]?(wheelMapping[ch]==='left'?'左輪':'右輪'):'尚未確認'}updateWheelMapping();
async function testChannel(ch){if(!requireCar())return;stop();let t=runToken;lastTestChannel=ch;$$('[data-answer]').forEach(x=>x.classList.remove('selected'));setRawMotor(ch==='a'?35:0,ch==='b'?35:0);$('#wheelFeedback').textContent='測試 '+ch.toUpperCase()+'：請觀察哪一個輪子轉動。';await sleep(800,t);if(t===runToken)setRawMotor(0,0)}
$('#testWheelA').onclick=()=>testChannel('a');$('#testWheelB').onclick=()=>testChannel('b');
$$('[data-answer]').forEach(b=>b.onclick=()=>{if(!requireCar())return;if(!lastTestChannel){notify('先選擇測試 A 或測試 B。');return}let answer=b.dataset.answer;if(answer!=='左邊'&&answer!=='右邊'){$('#wheelFeedback').textContent='無法辨認，請確認接線後再測試。';return}let side=answer==='左邊'?'left':'right',other=lastTestChannel==='a'?'b':'a';if(wheelMapping[other]===side){wheelMapping[other]=null;wheelMapping[lastTestChannel]=side;updateWheelMapping();$('#wheelFeedback').textContent='已更新 '+lastTestChannel.toUpperCase()+'，請重新測試 '+other.toUpperCase()+' 再套用。';return}wheelMapping[lastTestChannel]=side;$$('[data-answer]').forEach(x=>x.classList.toggle('selected',x===b));updateWheelMapping();if(wheelMapping.a&&wheelMapping.b){store('rover_map',wheelMapping.a);$('#wheelFeedback').textContent='已記住 A、B 與左右輪的對應。'}else $('#wheelFeedback').textContent='已記錄 '+lastTestChannel.toUpperCase()+'，請再測試 '+other.toUpperCase()+'。'});
$('#testStraight').onclick=async()=>{if(!requireCar())return;stop();let t=runToken;setMotor(40,40);$('#trimFeedback').textContent='測試中，請觀察小車是否走直線。';await sleep(900,t);if(t===runToken)setMotor(0,0)};function paintTrim(){$('#trimDot').style.left=(50+trim*5)+'%'}$$('[data-drift]').forEach(b=>b.onclick=()=>{if(!requireCar())return;trimHistory.push(trim);if(b.dataset.drift==='left')trim=Math.min(8,trim+1);if(b.dataset.drift==='right')trim=Math.max(-8,trim-1);paintTrim();$('#trimFeedback').textContent=b.dataset.drift==='straight'?'太好了！可以按「完成設定」。':'已小幅調整，請再測一次。'});$('#undoTrim').onclick=()=>{if(!requireCar())return;if(trimHistory.length)trim=trimHistory.pop();paintTrim();$('#trimFeedback').textContent='已撤銷上一次調整。'};$('#saveTrim').onclick=()=>{if(!requireCar())return;store('rover_trim',trim);setMotor(sim.left,sim.right);notify('已儲存在這支手機。')};trim=read('rover_trim',0);paintTrim();
const guides={parts:`<h2>先認識你的小車</h2><p>準備以下零件。</p><div class="parts-grid"><div class="part"><span>▰</span>雷切底盤</div><div class="part"><span>⚙</span>TT 馬達 × 2</div><div class="part"><span>◉</span>輪胎 × 2</div><div class="part"><span>◌</span>萬向輪</div><div class="part"><span>▥</span>電池盒</div><div class="part"><span>▦</span>控制板與驅動板</div></div><div class="warning">電池、降壓模組和電源線由老師先準備並檢查。</div>`,body:`<h2>車體與輪子</h2><figure class="chassis-figure"><img src="assets/chassis-layout.png" alt="雷切底板與四片馬達固定片的俯視圖，底板窄端在左側"><figcaption>左側窄端裝萬向輪；四片固定片用來安裝馬達。 <a href="https://www.thingiverse.com/thing:4738179" target="_blank" rel="noopener noreferrer">模型來源</a></figcaption></figure><div class="assembly-step"><h3>1. 固定馬達</h3><p>每顆馬達用兩片固定片，夾在馬達兩側，並對準底板的插槽及邊緣缺口。將兩支 M3 長螺絲穿過固定片和馬達的孔，再鎖上螺帽。</p><figure class="assembly-figure"><img src="assets/motor-fastening-3d.png" alt="兩支 M3 長螺絲穿過固定片與馬達，另一側以螺帽鎖緊的拆解示意圖"><figcaption>立體拆解示意；紅色虛線表示螺絲穿過的方向。</figcaption></figure></div><div class="assembly-step"><h3>2. 裝上輪子</h3><p>將輪胎凹槽對準馬達軸，輕輕壓上。另一側重複以上步驟。</p><figure class="assembly-figure"><img src="assets/motor-assembled.png" alt="輪子裝到馬達軸後的單側車體，兩片固定片位於馬達兩側"><figcaption>單側完成示意；底板以透明方式顯示。</figcaption></figure></div><div class="assembly-step"><h3>3. 安裝萬向輪</h3><p>將 M3 母母銅柱放在底板下方，從底板上方穿入 M3 × 6 mm 螺絲，鎖入銅柱。</p><figure class="assembly-figure"><img src="assets/caster-exploded.png?v=2" alt="萬向輪安裝拆解側視圖：底板上方是 M3 螺絲，下方是母母銅柱、萬向輪支架和 M3 螺絲"><figcaption>側面示意；各固定孔都用相同方式安裝。</figcaption></figure><p>把萬向輪支架的孔對準銅柱另一端，從支架下方穿入 M3 × 6 mm 螺絲，鎖入銅柱。</p><figure class="assembly-figure"><img src="assets/caster-assembled.png?v=2" alt="萬向輪固定完成側視圖：底板上方及支架下方各有螺絲，母母銅柱位於底板與支架之間"><figcaption>固定完成；示意圖只畫出側面可見的銅柱。</figcaption></figure><p>每根母母銅柱需要兩支螺絲：底板上方一支、萬向輪支架下方一支。</p></div><div class="assembly-step"><h3>4. 固定電池盒與電路</h3><p>將電池盒及電路板固定在底板上，留出開關與電池蓋的空間。</p></div><div class="warning">萬向輪孔數、孔距及螺絲咬合深度請依實物核對；銅柱長度需試裝至車身平穩。馬達與輪子外觀為簡化示意。</div>`,wiring:`<h2>小車接線</h2><p>先關閉電池盒開關。電源線由老師預先處理。</p><iframe class="wiring-3d" src="assets/wiring3d/index.html?v=15" title="小車 3D 分步接線圖" allowfullscreen loading="lazy"></iframe><p class="model-hint">拖曳可旋轉；控制板與驅動板翻至排針朝上。線長與彎曲方向以示意呈現。</p><h3>1. 電源線（老師）</h3><table class="wiring-table"><tr><th>從哪裡</th><th>接到哪裡</th></tr><tr><td>電池盒紅線公頭</td><td>LM2596 IN+ 母頭</td></tr><tr><td>電池盒黑線公頭</td><td>LM2596 IN− 母頭</td></tr><tr><td>LM2596 OUT+ 母頭</td><td>接一條 Y 線公頭；兩個母頭分別接 C3 5V、DRV8833 VCC</td></tr><tr><td>LM2596 OUT− 母頭</td><td>接另一條 Y 線公頭；兩個母頭分別接 C3 G、DRV8833 GND</td></tr></table><h3>2. 控制線</h3><table class="wiring-table"><tr><th>SuperMini C3</th><th>DRV8833</th></tr><tr><td>GPIO4</td><td>IN1</td></tr><tr><td>GPIO3</td><td>IN2</td></tr><tr><td>GPIO1</td><td>IN3</td></tr><tr><td>GPIO0</td><td>IN4</td></tr></table><h3>3. 馬達線</h3><table class="wiring-table"><tr><th>DRV8833</th><th>接到</th></tr><tr><td>OUT1、OUT2</td><td>左馬達兩條線</td></tr><tr><td>OUT3、OUT4</td><td>右馬達兩條線</td></tr></table><p>每顆馬達兩條線的方向可在「小車校正」調整。</p><h3>查看元件</h3><p class="model-hint">選擇零件後可旋轉模型。</p><div class="model-selector" role="group" aria-label="選擇元件模型"><button class="model-tab active" data-model="c3">控制板</button><button class="model-tab" data-model="drv8833">驅動板</button><button class="model-tab" data-model="lm2596">降壓模組</button><button class="model-tab" data-model="battery">電池盒</button><button class="model-tab" data-model="tt">TT 馬達</button><button class="model-tab" data-model="ywire">Y 分接線</button></div><iframe id="guideModel" class="guide-model" title="控制板 3D 模型" src="assets/models/c3.html?v=9" loading="lazy"></iframe>`,check:`<h2>開機前檢查</h2><ol><li>線是否插穩、車輪能自由轉動？</li><li>電池與電源極性請老師確認。</li><li>第一次測試時，把車輪架空。</li><li>測試前確認「緊急停止」在哪裡。</li><li>充電與 USB 燒錄時，請依老師指示斷開電池電源。</li></ol>`};function showGuide(key){$('#guideContent').innerHTML=guides[key];$$('[data-guide]').forEach(b=>b.classList.toggle('active',b.dataset.guide===key));if(key==='wiring'){$$('.model-tab').forEach(b=>b.onclick=()=>{$$('.model-tab').forEach(x=>x.classList.toggle('active',x===b));const f=$('#guideModel');f.src='assets/models/'+b.dataset.model+'.html?v=9';f.title=b.textContent+' 3D 模型'})}}$$('[data-guide]').forEach(b=>b.onclick=()=>showGuide(b.dataset.guide));showGuide('parts');

for(const [side,id] of [['left','testDirectionLeft'],['right','testDirectionRight']])$('#'+id).onclick=async()=>{if(!requireCar())return;stop();let t=runToken;setMotor(side==='left'?35:0,side==='right'?35:0);$('#directionTestStatus').textContent='請觀察'+(side==='left'?'左':'右')+'輪的方向。';await sleep(800,t);if(t===runToken)setMotor(0,0)};
$('#saveDirection').onclick=()=>{if(!requireCar())return;let current=read('rover_direction',{left:'forward',right:'forward'});for(const [side,id] of [['left','dirLeft'],['right','dirRight']]){if($('#'+id).value==='reverse')current[side]=current[side]==='reverse'?'forward':'reverse';$('#'+id).value='forward'}store('rover_direction',current);setMotor(sim.left,sim.right);$('#directionTestStatus').textContent='設定已儲存，請重新測試確認方向。';notify('已儲存設定，請重新測試確認。')};

window.addEventListener('message',e=>{const f=document.querySelector('.wiring-3d');if(e.origin!==location.origin||!f||e.source!==f.contentWindow)return;if(e.data?.type==='rover-focus-details'&&window.matchMedia('(max-width:760px)').matches){const y=f.getBoundingClientRect().top+window.scrollY-62;window.scrollTo({top:Math.max(0,y),behavior:'smooth'});return}if(e.data?.type!=='rover-wiring-height')return;const h=Number(e.data.height);if(Number.isFinite(h))f.style.height=Math.max(350,Math.min(2400,h+4))+'px'});

// Local connection: the car owns arbitration and stops on control timeout.
let connectionEpoch=0,serialPort=null,serialReader=null,serialReading=false,shareSupported=false;
const ipInput=$('#carIp'), codeInput=$('#carCode'), connectionStatus=$('#connectionStatus');
function validLocalIP(value){const p=value.split('.');if(p.length!==4||p.some(x=>!/^\d{1,3}$/.test(x)||Number(x)>255))return false;const [a,b]=p.map(Number);return a===10||(a===172&&b>=16&&b<=31)||(a===192&&b===168)||(a===169&&b===254)}
let lastConnectionState='disconnected';
function paintConnection(state){
 const messages={disconnected:'尚未連線',connecting:'正在連線…',free:'已連線，等待取得控制權',busy:'已連線，另一位組員控制中',owner:'已連線，你正在控制',error:'連線失敗。請確認小車與手機在同一網路，並允許瀏覽器存取區域網路。'};
 connectionStatus.textContent=state==='error'?'尚未連線':(messages[state]||state);if(state==='error'&&lastConnectionState!=='error')notify(messages.error,'error');lastConnectionState=state;
 const nav=$('#navConnect'),navLabels={disconnected:'未連線',connecting:'連線中',free:'可接手',busy:'他人控制',owner:'控制中',error:'連線失敗'};nav.querySelector('span').textContent=navLabels[state]||'未連線';$('#desktopConnectStatus').textContent=navLabels[state]||'未連線';$('#carConnect').setAttribute('aria-label','連線：'+(messages[state]||'尚未連線'));nav.dataset.connection=state;nav.setAttribute('aria-label',messages[state]||'尚未連線');
 $('#claimControl').hidden=!carConnected||state!=='free';$('#releaseControl').hidden=!carConnected||state!=='owner';$('#disconnectCar').hidden=!carConnected;
 $('#connectSubmit').disabled=state==='connecting'||carConnected;
}
function lostControl(){if(carOwner){runToken++;sim={left:0,right:0};carMotor={a:0,b:0};carOwner=false;$('#simMessage').textContent='控制權已交出或連線中斷。'}}

const sharedIp=new URL(location.href).searchParams.get('car');if(sharedIp&&validLocalIP(sharedIp))ipInput.value=sharedIp;else ipInput.value=read('rover_car_ip','');
$('#connectSubmit').onclick=()=>{
 const ip=ipInput.value.trim(),code=codeInput.value.trim();if(!validLocalIP(ip)||!/^\d{6}$/.test(code)){notify('請輸入區域網路 IP 與 6 位數配對碼。','error');return}
 let ws;const socketUrl=`ws://${ip}:81/`;try{try{ws=new WebSocket(socketUrl,{targetAddressSpace:'local'})}catch(e){if(!(e instanceof SyntaxError)&&e?.name!=='SyntaxError'&&e?.name!=='TypeError')throw e;ws=new WebSocket(socketUrl)}}catch(e){paintConnection('error');return}
 const epoch=++connectionEpoch;carSocket=ws;store('rover_car_ip',ip);paintConnection('connecting');
 const timer=setTimeout(()=>{if(epoch===connectionEpoch&&!carConnected){ws.close();paintConnection('error')}},8000);
 ws.onopen=()=>{if(epoch===connectionEpoch)ws.send('AUTH:'+code)};
 ws.onmessage=e=>{if(epoch!==connectionEpoch||typeof e.data!=='string')return;
  if(e.data==='AUTH:OK'){clearTimeout(timer);carConnected=true;paintConnection('free')}
  else if(e.data==='CAPS:SHARE1'){shareSupported=true}
  else if(e.data.startsWith('SHARE:')){handleShareMessage(e.data)}
  else if(e.data==='AUTH:FAIL'){clearTimeout(timer);paintConnection('error')}
  else if(e.data.startsWith('STATE:')){let v=e.data.slice(6);if(v!=='OWNER')lostControl();carOwner=v==='OWNER';paintConnection(v==='OWNER'?'owner':v==='BUSY'?'busy':'free')}
 };
 ws.onerror=()=>{if(epoch===connectionEpoch&&!carConnected)paintConnection('error')};
 ws.onclose=()=>{clearTimeout(timer);if(epoch!==connectionEpoch)return;let was=carConnected;lostControl();carConnected=false;carSocket=null;shareSupported=false;shareDisconnected();paintConnection(was?'disconnected':'error');if(was)notify('小車連線已中斷。')};
};
$('#claimControl').onclick=()=>sendCar('CLAIM');
$('#releaseControl').onclick=()=>{runToken++;sim={left:0,right:0};carMotor={a:0,b:0};sendCar('RELEASE')};
$('#disconnectCar').onclick=()=>{if(carOwner)sendCar('RELEASE');carSocket?.close()};
$('#showCarQr').onclick=async()=>{
 const ip=ipInput.value.trim(),code=codeInput.value.trim();if(!validLocalIP(ip)||!/^\d{6}$/.test(code)){notify('請先填入小車 IP 和 6 位數配對碼。');return}
 try{const qr=await import('./vendor/rover-qr.js');const url=new URL(location.href);url.searchParams.delete('car');url.hash=new URLSearchParams({join:ip,code}).toString();await qr.toCanvas($('#carQrCanvas'),url.href,{width:240,margin:3,errorCorrectionLevel:'M'});$('#carQrPanel').hidden=false;$('#carQrPanel').scrollIntoView({block:'nearest',behavior:'smooth'})}catch(e){console.error('QR generation failed',e);notify('無法產生 QR Code，請重新整理後再試。')}
};
$('#closeCarQr').onclick=()=>{$('#carQrPanel').hidden=true};
for(const field of [ipInput,codeInput])field.addEventListener('input',()=>{$('#carQrPanel').hidden=true});
$('#shareCar').onclick=async()=>{let ip=ipInput.value.trim();if(!validLocalIP(ip)){notify('先輸入小車 IP。');return}let url=new URL(location.href);url.searchParams.set('car',ip);url.hash='';try{if(navigator.share)await navigator.share({title:'加入小車',url:url.href});else{await navigator.clipboard.writeText(url.href);notify('已複製連結；配對碼請另外告訴組員。')}}catch(e){if(e.name!=='AbortError')notify('無法分享連結，請將 IP 和配對碼告訴組員。')}};
setInterval(()=>{if(!carConnected||!carOwner||document.hidden)return;if(!sendCar('PING'))return;if(carMotor.a||carMotor.b)sendCar(`M:${Math.round(carMotor.a)},${Math.round(carMotor.b)}`)},150);
let wifiAttempt=null,wifiTimer=null,serialQueryBusy=false,lastSerialState='',serialHandshakeTimer=null,serialAcknowledged=false;
function serialError(message,shortStatus='USB 或 Wi-Fi 尚未就緒'){const status=$('#serialStatus');status.textContent=shortStatus;notify(message,'error')}
function serialLog(message){const list=$('#serialLog'),item=document.createElement('li'),time=new Date().toLocaleTimeString('zh-TW',{hour12:false});item.textContent=time+' '+message;list.append(item);while(list.children.length>16)list.firstElementChild.remove()}
function endWifiAttempt(){clearInterval(wifiTimer);wifiTimer=null;wifiAttempt=null}
function serialAcknowledgement(){serialAcknowledged=true;clearInterval(serialHandshakeTimer);serialHandshakeTimer=null;$('#serialSave').disabled=false}
function startSerialHandshake(){clearInterval(serialHandshakeTimer);serialAcknowledged=false;let started=Date.now();serialHandshakeTimer=setInterval(async()=>{if(!serialPort||serialAcknowledged){clearInterval(serialHandshakeTimer);serialHandshakeTimer=null;return}if(Date.now()-started>=12000){clearInterval(serialHandshakeTimer);serialHandshakeTimer=null;serialError('USB 已開啟，但小車沒有回應。請按一下板上的 RESET，或確認已燒錄小車韌體。');serialLog('未收到小車回應，請按 RESET 或檢查韌體。');return}if(!serialQueryBusy){serialQueryBusy=true;try{await serialWrite('STATUS')}catch(e){}finally{serialQueryBusy=false}}},2000)}
function serialStatusLine(line){
 const parts=line.split('\t');
 if(parts[0]==='PAIR'&&validLocalIP(parts[1])&&/^\d{6}$/.test(parts[2])){
  serialAcknowledgement();let wasAttempt=!!wifiAttempt;endWifiAttempt();ipInput.value=parts[1];codeInput.value=parts[2];store('rover_car_ip',parts[1]);$('#serialStatus').textContent='Wi-Fi 已連線，小車 IP 與配對碼已填入上方。';
  if(lastSerialState!=='PAIR'||wasAttempt)serialLog('小車已連上 Wi-Fi；IP：'+parts[1]+'，配對碼已填入。');lastSerialState='PAIR';return;
 }
 if(parts[0]==='STATUS'){
  const state=parts[1];if(['READY','CONNECTING','DISCONNECTED'].includes(state))serialAcknowledgement();if(state==='READY'&&serialPort)serialWrite('STATUS').catch(()=>{});if(wifiAttempt){wifiAttempt.responses++;if(state==='CONNECTING'){wifiAttempt.ack=true;if(lastSerialState!=='CONNECTING')serialLog('小車已收到設定，正在連線 Wi-Fi。');lastSerialState='CONNECTING'}return}
  const labels={READY:'USB 已連接，可以設定 Wi-Fi。',CONNECTING:'小車正在連線 Wi-Fi。',DISCONNECTED:'小車尚未連上 Wi-Fi。'};
  if(labels[state]){$('#serialStatus').textContent=labels[state];if(lastSerialState!==state)serialLog(labels[state]);lastSerialState=state}return;
 }
 if(parts[0]==='ERROR'){endWifiAttempt();serialError('小車回報 Wi-Fi 設定格式錯誤。','Wi-Fi 尚未連線');serialLog('小車回報設定格式錯誤。');lastSerialState='ERROR'}
}
async function serialWrite(line){if(!serialPort?.writable)throw Error('USB 尚未連接');let writer=serialPort.writable.getWriter();try{await writer.write(new TextEncoder().encode(line+'\n'))}finally{writer.releaseLock()}}
function startWifiAttempt(){
 endWifiAttempt();lastSerialState='';wifiAttempt={started:Date.now(),responses:0,ack:false};serialLog('已傳送 Wi-Fi 設定，等待小車回應。');
 $('#serialStatus').textContent='已送出設定，正在等待小車連線…';
 wifiTimer=setInterval(async()=>{
  if(!wifiAttempt)return;let elapsed=Math.floor((Date.now()-wifiAttempt.started)/1000);
  if(elapsed>=25){let responded=wifiAttempt.responses>0;endWifiAttempt();let msg=responded?'小車有回應，但 25 秒內尚未連上。請檢查 Wi-Fi 名稱、密碼與 2.4 GHz 設定。':'25 秒內沒有收到小車回應。請確認 USB 序列埠和小車韌體，再重新讀取。';serialError(msg,'Wi-Fi 尚未連線');serialLog(msg);return}
  $('#serialStatus').textContent=(wifiAttempt.ack?'小車正在連線 Wi-Fi':'等待小車回應')+'…（'+elapsed+' 秒）';
  if(!serialQueryBusy){serialQueryBusy=true;try{await serialWrite('STATUS')}catch(e){endWifiAttempt();serialError('USB 傳送失敗，請重新讀取小車。');serialLog('USB 傳送失敗。')}finally{serialQueryBusy=false}}
 },2000)
}
$('#serialConnect').onclick=async()=>{
 if(!('serial' in navigator)){ serialError('請使用電腦版 Chrome 或 Edge 的 HTTPS 網頁。');serialLog('此瀏覽器不支援 Web Serial。');return}
 try{serialPort=await navigator.serial.requestPort();await serialPort.open({baudRate:115200});serialReading=true;lastSerialState='';serialLog('USB 序列埠已開啟，正在查詢小車。');$('#serialStatus').textContent='USB 已開啟，正在查詢小車…';$('#serialSave').disabled=true;$('#serialDisconnect').disabled=false;$('#serialConnect').disabled=true;startSerialHandshake();
  (async()=>{let buf='';try{while(serialPort?.readable&&serialReading){serialReader=serialPort.readable.getReader();try{while(serialReading){const {value,done}=await serialReader.read();if(done)break;buf+=new TextDecoder().decode(value);let idx;while((idx=buf.indexOf('\n'))>=0){serialStatusLine(buf.slice(0,idx).replace(/\r$/, ''));buf=buf.slice(idx+1)}if(buf.length>1000)buf=''}}finally{serialReader.releaseLock();serialReader=null}}}catch(e){if(serialReading){endWifiAttempt();serialError('USB 連線已中斷，請結束 USB 後重新連接。');serialLog('USB 讀取中斷。')}}finally{serialReading=false}})();
  await serialWrite('STATUS');
 }catch(e){serialError('無法開啟 USB，請確認韌體已燒錄並關閉其他序列埠程式。');serialLog('無法開啟 USB 序列埠。');serialPort=null}
};
$('#serialSave').onclick=async()=>{let name=$('#wifiName').value,pass=$('#wifiPassword').value;if(!name||/[\t\r\n]/.test(name+pass)||new TextEncoder().encode(name).length>32||new TextEncoder().encode(pass).length>63){serialError('請檢查 Wi-Fi 名稱與密碼。','Wi-Fi 尚未連線');return}try{startWifiAttempt();await serialWrite(`WIFI\t${name}\t${pass}`);$('#wifiPassword').value=''}catch(e){endWifiAttempt();serialError('USB 傳送失敗，請重新讀取小車。');serialLog('USB 傳送失敗。')}};
$('#serialDisconnect').onclick=async()=>{endWifiAttempt();clearInterval(serialHandshakeTimer);serialHandshakeTimer=null;serialAcknowledged=false;serialReading=false;try{await serialReader?.cancel();await serialPort?.close()}catch(e){}serialPort=null;$('#serialSave').disabled=true;$('#serialDisconnect').disabled=true;$('#serialConnect').disabled=false;$('#serialStatus').textContent='USB 已結束。';serialLog('USB 已結束。')};

// Prebuilt ESP32-C3 images: only these four flash regions are written; NVS is not deliberately erased.
const firmwareImages=[
 {name:'bootloader.bin',address:0x0,sha:'9b2fa5e4af7cf282b2db5ed726b26bcca0aec7946eb3fdacc14444195ba754b3'},
 {name:'partitions.bin',address:0x8000,sha:'148b959cbff1c38aa8e1d5c0ba9d612c54997b945e56a63f41223eef650653a1'},
 {name:'boot_app0.bin',address:0xe000,sha:'f94c5d786a7a8fab06ac5d10e33bf37711a6697636dc037559ea19cc410a17f0'},
 {name:'firmware.bin',address:0x10000,sha:'de27205d3ad5b6f8b7d1d331c32a2d8c189bd30d70b202805f93973005c71ed6'}
];
$('#flashFirmware').onclick=async()=>{
 const status=$('#flashStatus'),button=$('#flashFirmware'),progress=$('#flashProgress');
 if(!('serial' in navigator)){notify('請使用電腦版 Chrome 或 Edge 開啟 HTTPS 網頁。','error');return}
 if(serialPort){notify('請先按「結束 USB」，再進行燒錄。','error');return}
 let transport=null,port=null,finished=false,resetOk=true;
 try{
  // Keep requestPort inside the user gesture, before network or dynamic imports.
  port=await navigator.serial.requestPort();button.disabled=true;$('#serialConnect').disabled=true;status.textContent='準備韌體…';progress.hidden=false;progress.value=0;
  const [{ESPLoader,Transport},{md5},...responses]=await Promise.all([import('./vendor/esptool-js-0.7.1.js'),import('./vendor/rover-md5.js'),...firmwareImages.map(f=>fetch('./firmware/bin/'+f.name,{cache:'no-cache'}))]);
  const files=[];for(let i=0;i<responses.length;i++){
   if(!responses[i].ok)throw new Error('無法下載韌體檔案');let data=new Uint8Array(await responses[i].arrayBuffer());let digest=new Uint8Array(await crypto.subtle.digest('SHA-256',data));let hex=Array.from(digest,v=>v.toString(16).padStart(2,'0')).join('');if(hex!==firmwareImages[i].sha)throw new Error('韌體檔案檢查失敗，請重新整理後再試');files.push({data,address:firmwareImages[i].address});
  }
  transport=new Transport(port,true);const terminal={clean(){},writeLine(){},write(){}};
  const loader=new ESPLoader({transport,baudrate:115200,terminal});status.textContent='正在辨識板子，請稍候…';const chip=await loader.main();
  if(!/^ESP32-C3\b/.test(chip))throw new Error('偵測到 '+chip+'，只支援 ESP32-C3');
  const size=await loader.detectFlashSize();if(!size||!/^\d+MB$/.test(size)||parseInt(size,10)<4)throw new Error('無法確認至少 4MB 的快閃記憶體，已停止燒錄');
  let completed=0;const total=files.reduce((sum,f)=>sum+f.data.length,0);status.textContent='正在燒錄，請勿拔除 USB…';
  await loader.writeFlash({fileArray:files,flashMode:'dio',flashFreq:'80m',flashSize:'4MB',eraseAll:false,compress:true,calculateMD5Hash:md5,reportProgress:(i,written,fileTotal)=>{completed=files.slice(0,i).reduce((sum,f)=>sum+f.data.length,0);progress.value=Math.min(99,Math.round((completed+files[i].data.length*(fileTotal?written/fileTotal:0))/total*100))}});
  finished=true;progress.value=100;try{await loader.after('hard_reset')}catch(e){resetOk=false}
  status.textContent=resetOk?'燒錄完成並驗證成功。接著按「讀取小車」設定 Wi-Fi。':'燒錄完成並驗證成功。請重新插拔 USB，再按「讀取小車」。';
 }catch(e){
  if(e?.name==='NotFoundError')status.textContent='已取消選擇序列埠。';
  else {console.error('Flash failed',e);status.textContent='燒錄未完成。';notify('燒錄未完成：'+(e?.message||'請檢查 USB 連接')+'。可按住 BOOT、按一下 RESET 後重試。','error')}
 }finally{
  if(transport){try{await transport.disconnect()}catch(e){if(finished)status.textContent='燒錄完成並驗證成功。請重新插拔 USB，再按「讀取小車」。'}}
  button.disabled=false;$('#serialConnect').disabled=!!serialPort;
 }
};

// A scanned code carries the IP and pairing code in the URL fragment, not in the HTTP request.
async function handleScannedCar(){
 const params=new URLSearchParams(location.hash.slice(1)),ip=params.get('join'),code=params.get('code');
 if(!ip||!code)return;
 history.replaceState(history.state,'',location.pathname+location.search);
 if(!validLocalIP(ip)||!/^\d{6}$/.test(code)){notify('QR Code 的小車資訊無效。');return}
 const alreadyConnected=carConnected||carSocket?.readyState===WebSocket.CONNECTING;
 ipInput.value=ip;codeInput.value=code;$('#carQrPanel').hidden=true;showPage('connection');
 if(alreadyConnected){connectionStatus.textContent='已填入新的小車資訊；請先斷線，再按「連線」。';return}
 let permission='prompt';try{if(navigator.permissions?.query)permission=(await navigator.permissions.query({name:'local-network'})).state}catch(e){}
 if(permission==='granted'){$('#connectSubmit').click()}
 else if(permission==='denied'){connectionStatus.textContent='尚未連線';notify('請在瀏覽器網站設定允許區域網路，然後按「連線」。','error');}
 else connectionStatus.textContent='小車資訊已填好。請按「連線」，並允許存取區域網路。';
}
window.addEventListener('hashchange',handleScannedCar);
window.addEventListener('pageshow',handleScannedCar);
handleScannedCar();

// A share is a one-time snapshot relayed by the authenticated car; it is never executed on receipt.
const SHARE_LIMIT=131072,shareDialog=$('#shareDialog'),receiveDialog=$('#receiveDialog');
let incomingShare=null,pendingShare=null,shareAck=null,shareSending=false;
function projectSnapshot(){return {version:1,blocks:Blockly.serialization.workspaces.save(workspace),buttons:buttons.filter(b=>b.id!==pendingNewButtonId).map(b=>({...b})),activeStart:read('rover_active_start',null)}}
function shareRoots(){return workspace.getTopBlocks(true)}
function shareRootName(b){if(b.type==='procedures_defnoreturn')return '自訂功能：'+b.getProcedureDef()[0];if(b.type==='start_car')return '當開始執行';return b.toString(55)||'積木'}
function showShareChoices(){
 let list=$('#shareChoices'),all=$('#shareSelectAll');list.replaceChildren();all.checked=true;all.indeterminate=false;
 function heading(text,kind){let h=document.createElement('h3');h.className='share-group-title';h.dataset.shareSection=kind;h.textContent=text;list.append(h)}
 function addChoice(text,value,kind,color){let l=document.createElement('label'),c=document.createElement('input'),t=document.createElement('span');c.type='checkbox';c.value=value;c.checked=true;c.dataset.shareKind=kind;c.onchange=updateShareSelectAll;if(color){let dot=document.createElement('span');dot.className='share-button-color';dot.style.backgroundColor=color;l.append(c,dot,t)}else l.append(c,t);t.textContent=text;list.append(l)}
 heading('積木','block');let roots=shareRoots();for(const b of roots)addChoice(shareRootName(b),b.id,'block');if(!roots.length){let empty=document.createElement('span');empty.className='share-empty';empty.textContent='沒有積木';list.append(empty)}
 heading('遙控器按鈕','button');let saved=buttons.filter(b=>b.id!==pendingNewButtonId);for(const [index,b] of saved.entries()){let def=buttonFunction(b);addChoice(def?def.getProcedureDef()[0]:'未設定功能',String(index),'button',b.color)}if(!saved.length){let empty=document.createElement('span');empty.className='share-empty';empty.textContent='沒有按鈕';list.append(empty)}updateShareCounts();
}
function updateShareCounts(){for(const [kind,id,label] of [['block','shareBlocksShortcut','積木'],['button','shareButtonsShortcut','遙控器按鈕']]){let items=$$(`#shareChoices input[data-share-kind="${kind}"]`);$('#'+id).textContent=`${label} ${items.filter(x=>x.checked).length}/${items.length}`}}
function updateShareSelectAll(){let items=$$('#shareChoices input'),count=items.filter(x=>x.checked).length;$('#shareSelectAll').checked=items.length>0&&count===items.length;$('#shareSelectAll').indeterminate=count>0&&count<items.length;updateShareCounts()}
function scrollShareSection(kind){let list=$('#shareChoices'),heading=list.querySelector(`[data-share-section="${kind}"]`);if(heading)list.scrollTo({top:list.scrollTop+heading.getBoundingClientRect().top-list.getBoundingClientRect().top,behavior:'smooth'})}
$('#shareBlocksShortcut').onclick=()=>scrollShareSection('block');$('#shareButtonsShortcut').onclick=()=>scrollShareSection('button');
$('#shareSelectAll').onchange=()=>{$$('#shareChoices input').forEach(x=>x.checked=$('#shareSelectAll').checked);$('#shareSelectAll').indeterminate=false;updateShareCounts()};
function openShare(event){if(!workspace)return;if(pendingNewButtonId!==null)closeControllerPanel();showShareChoices();$('#shareStatus').textContent='';$('#shareRestore').hidden=!read('rover_share_backup',null);shareDialog.showModal();if(event?.currentTarget?.id==='controllerShare')requestAnimationFrame(()=>scrollShareSection('button'))}
$('#openShare').onclick=openShare;$$('[data-open-share]').forEach(button=>button.addEventListener('click',openShare));$('#shareClose').onclick=()=>shareDialog.close();
function chosenProject(){let project=projectSnapshot();if($('#shareSelectAll').checked)return project;
 const ids=new Set($$('#shareChoices input[data-share-kind="block"]:checked').map(x=>x.value));
 const buttonIndexes=new Set($$('#shareChoices input[data-share-kind="button"]:checked').map(x=>Number(x.value)));
 if(!ids.size&&!buttonIndexes.size)throw Error('請先勾選要分享的積木或按鈕。');
 // Button functions and all functions called by selected stacks are required dependencies.
 let roots=shareRoots(),byName=new Map(customFunctions().map(b=>[b.getProcedureDef()[0],b])),todo=roots.filter(b=>ids.has(b.id));
 project.buttons=project.buttons.filter((b,index)=>{if(!buttonIndexes.has(index))return false;let def=buttonFunction(b);if(def&&!ids.has(def.id)){ids.add(def.id);todo.push(def)}return true});
 for(let i=0;i<todo.length;i++)for(const b of todo[i].getDescendants(false)){if(b.type==='procedures_callnoreturn'){let def=byName.get(b.getProcedureCall());if(def&&!ids.has(def.id)){ids.add(def.id);todo.push(def)}}}
 if(project.blocks.blocks)project.blocks.blocks.blocks=project.blocks.blocks.blocks.filter(b=>ids.has(b.id));
 if(!ids.has(project.activeStart))project.activeStart=null;return project;
}
function validateProject(p){if(!p||p.version!==1||!p.blocks||!Array.isArray(p.buttons)||p.buttons.length>100)throw Error('作品格式不正確。');
 const allowed=new Set(['start_car','both_motors','single_motor','wait_car','stop_car','repeat_car','procedures_defnoreturn','procedures_callnoreturn']);let count=0;
 function checkBlock(b){if(!b||typeof b!=='object'||!allowed.has(b.type)||++count>1000)throw Error('作品包含不支援的積木。');if(b.next?.block)checkBlock(b.next.block);for(const v of Object.values(b.inputs||{})){if(v.block)checkBlock(v.block);if(v.shadow)checkBlock(v.shadow)}}
 let roots=p.blocks.blocks?.blocks||[];if(!Array.isArray(roots)||roots.length>200)throw Error('作品格式不正確。');for(const b of roots)checkBlock(b);
 for(const b of p.buttons){if(!b||!Number.isFinite(Number(b.x))||!Number.isFinite(Number(b.y))||Number(b.x)<0||Number(b.x)>100||Number(b.y)<0||Number(b.y)>100||!/^#[0-9a-f]{6}$/i.test(b.color||'')||typeof b.functionName!=='string'||b.functionName.length>100)throw Error('遙控器資料不正確。')}
 let test=new Blockly.Workspace();try{Blockly.serialization.workspaces.load(p.blocks,test)}finally{test.dispose()}}
function applyProject(p,keepBackup){validateProject(p);const previous=projectSnapshot();if(keepBackup&&!read('rover_share_backup',null))localStorage.setItem('rover_share_backup',JSON.stringify(previous));
 stop();if(recording)finishRecording();if(pendingNewButtonId!==null)closeControllerPanel();
 try{loadBlocks(p.blocks);buttons=p.buttons.map(b=>({...b}));pendingNewButtonId=null;selected=buttons[0]?.id;store('rover_blocks',Blockly.serialization.workspaces.save(workspace));saveButtons();store('rover_active_start',p.activeStart||null);drawButtons();renderEditor();resizeWorkspace()}
 catch(e){loadBlocks(previous.blocks);buttons=previous.buttons;selected=buttons[0]?.id;store('rover_blocks',previous.blocks);saveButtons();store('rover_active_start',previous.activeStart);drawButtons();renderEditor();throw e}}
$('#shareRestore').onclick=()=>{let p=read('rover_share_backup',null);if(!p)return;if(!confirm('復原原本的積木和遙控器？目前作品會被取代。'))return;try{applyProject(p,false);localStorage.removeItem('rover_share_backup');$('#shareRestore').hidden=true;shareDialog.close();notify('已復原原本的作品。')}catch(e){notify('無法復原作品，請確認瀏覽器儲存空間。','error')}};
function waitShareAck(expected){return new Promise((resolve,reject)=>{let timer=setTimeout(()=>{shareAck=null;reject(Error('分享逾時，請確認組員仍在線上。'))},7000);shareAck={expected,resolve:()=>{clearTimeout(timer);shareAck=null;resolve()},reject:()=>{clearTimeout(timer);shareAck=null;reject(Error('分享中斷，請重試。'))}}})}
async function sendShareFrame(msg,expected){let ack=waitShareAck(expected);if(!sendCar(msg)){shareAck.reject();}return ack}
$('#shareSend').onclick=async()=>{if(shareSending)return;if(!carConnected){notify('請先連接小車，再分享給組員。');return}if(!shareSupported){notify('請先更新小車韌體，才能分享作品。');return}let id='';try{let project=chosenProject(),bytes=new TextEncoder().encode(JSON.stringify(project));if(bytes.length>SHARE_LIMIT)throw Error('作品太大，請減少積木後再分享。');let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));let data=btoa(binary),chunks=data.match(/.{1,800}/g)||[];id=Array.from(crypto.getRandomValues(new Uint8Array(6)),x=>x.toString(16).padStart(2,'0')).join('');shareSending=true;$('#shareSend').disabled=true;$('#shareStatus').textContent='正在分享…';runToken++;sim={left:0,right:0};carMotor={a:0,b:0};await sendShareFrame(`SHARE:BEGIN:${id}:${chunks.length}:${bytes.length}`,`${id}:BEGIN`);for(let i=0;i<chunks.length;i++)await sendShareFrame(`SHARE:CHUNK:${id}:${i}:${chunks[i]}`,`${id}:${i}`);await sendShareFrame(`SHARE:END:${id}`,`${id}:END`);$('#shareStatus').textContent='已送出，請組員確認接收。'}catch(e){if(id&&carConnected)sendCar('SHARE:CANCEL:'+id);$('#shareStatus').textContent=e.message||'分享失敗，請再試一次。'}finally{shareSending=false;$('#shareSend').disabled=false}};
function shareDisconnected(){incomingShare=null;if(shareAck)shareAck.reject()}
// Build a merge without changing the live workspace until all choices are complete.
const normFunctionName=name=>String(name||'').trim().toLocaleLowerCase();
function projectRoots(p){return p.blocks.blocks?.blocks||[]}
function functionName(b){return String(b.fields?.NAME||'').trim()}
function canonicalBlock(value){if(Array.isArray(value))return value.map(canonicalBlock);if(!value||typeof value!=='object')return value;let out={};for(const k of Object.keys(value).sort()){if(k==='id'||k==='x'||k==='y')continue;out[k]=canonicalBlock(value[k])}return out}
function sameFunction(a,b){let aa=canonicalBlock(a),bb=canonicalBlock(b);if(aa.fields?.NAME)aa.fields.NAME=normFunctionName(aa.fields.NAME);if(bb.fields?.NAME)bb.fields.NAME=normFunctionName(bb.fields.NAME);return JSON.stringify(aa)===JSON.stringify(bb)}
function describeFunction(def){let out=[];function visit(b){if(!b)return;const f=b.fields||{},dir=v=>v==='1'?'前進':v==='-1'?'後退':'停止';switch(b.type){case 'both_motors':out.push(`左右馬達：左${dir(f.LD)} ${f.LS}%，右${dir(f.RD)} ${f.RS}%`);break;case 'single_motor':out.push(`${f.SIDE==='left'?'左':'右'}馬達：${dir(f.DIR)} ${f.SPEED}%`);break;case 'wait_car':out.push(`等待 ${f.SEC} 秒`);break;case 'stop_car':out.push('停止全部馬達');break;case 'repeat_car':out.push(`重複 ${f.COUNT} 次`);break;case 'procedures_callnoreturn':out.push(`執行 ${b.extraState?.name||'自訂功能'}`);break}for(const v of Object.values(b.inputs||{}))visit(v.block);visit(b.next?.block)}visit(def.inputs?.STACK?.block);return out.join(' → ')||'（沒有動作）'}
function findMergeConflicts(current,incoming){const existing=new Map(projectRoots(current).filter(b=>b.type==='procedures_defnoreturn').map(b=>[normFunctionName(functionName(b)),b]));return projectRoots(incoming).filter(b=>b.type==='procedures_defnoreturn').map(b=>({incoming:b,existing:existing.get(normFunctionName(functionName(b)))})).filter(x=>x.existing&&!sameFunction(x.existing,x.incoming))}
function renderReceiveChoices(){const merge=$('input[name="receiveMode"]:checked').value==='merge',box=$('#receiveConflicts');box.replaceChildren();$('#receiveHint').textContent=merge?'原有作品會保留；接收後也能復原。':'目前作品會被取代；接收後也能復原。';if(!merge||!pendingShare)return;const conflicts=findMergeConflicts(projectSnapshot(),pendingShare);if(conflicts.length)$('#receiveHint').textContent='選擇使用分享版本會更新原本的同名功能；接收後可以復原。';for(const [index,c] of conflicts.entries()){let card=document.createElement('section');card.className='receive-conflict';let heading=document.createElement('h3');heading.textContent='「'+functionName(c.incoming)+'」內容不同';card.append(heading);let dl=document.createElement('dl');for(const [label,block] of [['原本',c.existing],['分享',c.incoming]]){let dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=describeFunction(block);dl.append(dt,dd)}card.append(dl);let sel=document.createElement('select');sel.dataset.conflict=String(index);sel.setAttribute('aria-label','選擇「'+functionName(c.incoming)+'」的版本');for(const [text,val] of [['請選擇',''],['保留原本','keep'],['使用分享版本','replace'],['分享版本重新命名','rename']])sel.add(new Option(text,val));let input=document.createElement('input');input.type='text';input.maxLength=100;input.value=functionName(c.incoming)+'（分享）';input.setAttribute('aria-label','分享版本的新名稱');input.hidden=true;sel.onchange=()=>{input.hidden=sel.value!=='rename'};card.append(sel,input);box.append(card)}}
$$('input[name="receiveMode"]').forEach(r=>r.addEventListener('change',renderReceiveChoices));
function mergeProject(current,received){const result=structuredClone(current),incoming=structuredClone(received),existingRoots=projectRoots(result),incomingRoots=projectRoots(incoming),existingDefs=new Map(existingRoots.filter(b=>b.type==='procedures_defnoreturn').map(b=>[normFunctionName(functionName(b)),b]));const conflicts=findMergeConflicts(current,received),choices=new Map();for(const [i,c] of conflicts.entries()){const sel=$(`#receiveConflicts select[data-conflict="${i}"]`);if(!sel?.value)throw Error('請先選擇每個同名功能要使用的版本。');let name=sel.parentElement.querySelector('input').value.trim();if(sel.value==='rename'&&!name)throw Error('請輸入重新命名的功能名稱。');choices.set(normFunctionName(functionName(c.incoming)),{action:sel.value,name})}
 const reserved=new Set([...existingDefs.keys(),...incomingRoots.filter(b=>b.type==='procedures_defnoreturn').map(b=>normFunctionName(functionName(b)))]);for(const choice of choices.values())if(choice.action==='rename'){let k=normFunctionName(choice.name);if(reserved.has(k))throw Error('新名稱已存在，請換一個名稱。');reserved.add(k)}
 const defs=new Map(),renames=new Map(),removeExisting=new Set(),added=[];let bottom=Math.max(0,...existingRoots.map(b=>Number(b.y)||0))+200;
 for(const root of incomingRoots){if(root.type!=='procedures_defnoreturn'){added.push(root);continue}let oldName=functionName(root),key=normFunctionName(oldName),old=existingDefs.get(key),choice=choices.get(key),oldId=root.id;
  if(old&&(!choice||choice.action==='keep')){defs.set(oldId,{id:old.id,name:functionName(old)});renames.set(key,functionName(old));continue}
  if(old&&choice?.action==='replace'){removeExisting.add(old.id);defs.set(oldId,{id:old.id,name:functionName(old)});renames.set(key,functionName(old));root.id=old.id;root.fields.NAME=functionName(old);root.x=old.x;root.y=old.y;root._keepRootId=true;added.push(root);continue}
  let name=choice?.action==='rename'?choice.name:oldName;renames.set(key,name);root.fields.NAME=name;let id=Blockly.utils.idGenerator.genUid();defs.set(oldId,{id,name});root.id=id;root._keepRootId=true;added.push(root)}
 function rewrite(b,isRoot=false){if(!b)return;if(!isRoot||!b._keepRootId)b.id=Blockly.utils.idGenerator.genUid();delete b._keepRootId;if(b.type==='procedures_callnoreturn'&&b.extraState?.name){let name=renames.get(normFunctionName(b.extraState.name));if(name)b.extraState.name=name}if(b.next?.block)rewrite(b.next.block);for(const v of Object.values(b.inputs||{})){if(v.block)rewrite(v.block);if(v.shadow)rewrite(v.shadow)}}
 for(const root of added){let replacement=existingRoots.find(b=>b.id===root.id&&removeExisting.has(b.id));if(!replacement){root.x=(Number(root.x)||0)+40;root.y=(Number(root.y)||0)+bottom}rewrite(root,true)}
 result.blocks.blocks=result.blocks.blocks||{languageVersion:0,blocks:[]};result.blocks.blocks.blocks=existingRoots.filter(b=>!removeExisting.has(b.id)).concat(added);
 for(const button of incoming.buttons){let target=defs.get(button.functionId);if(!target&&!button.functionId){let name=renames.get(normFunctionName(button.functionName));if(name){let orig=projectRoots(received).find(b=>b.type==='procedures_defnoreturn'&&normFunctionName(functionName(b))===normFunctionName(button.functionName));target=orig&&defs.get(orig.id)}}let copy={...button,id:Blockly.utils.idGenerator.genUid()};if(target){copy.functionId=target.id;copy.functionName=target.name}if(!result.buttons.some(b=>b.functionId===copy.functionId&&b.functionName===copy.functionName&&Number(b.x)===Number(copy.x)&&Number(b.y)===Number(copy.y)&&b.color===copy.color)){let free=(x,y)=>!result.buttons.some(b=>Math.abs(Number(b.x)-x)<25&&Math.abs(Number(b.y)-y)<19);if(!free(Number(copy.x),Number(copy.y))){let candidates=[];for(let x=12;x<=88;x+=19)for(let y=8;y<=92;y+=21)if(free(x,y))candidates.push({x,y});candidates.sort((a,b)=>(a.x-copy.x)**2+(a.y-copy.y)**2-(b.x-copy.x)**2-(b.y-copy.y)**2);if(candidates.length){copy.x=candidates[0].x;copy.y=candidates[0].y}}result.buttons.push(copy)}}
 validateProject(result);return result}

function handleShareMessage(msg){if(msg.startsWith('SHARE:ACK:')){if(shareAck&&msg.slice(10)===shareAck.expected)shareAck.resolve();return}if(msg==='SHARE:ERROR'){if(shareAck)shareAck.reject();return}
 if(msg.startsWith('SHARE:ABORT:')){incomingShare=null;if(shareAck)shareAck.reject();return}
 if(msg.startsWith('SHARE:BEGIN:')){let parts=msg.split(':'),id=parts[2],total=Number(parts[3]),size=Number(parts[4]);if(parts.length!==5||!/^\w{12}$/.test(id)||!Number.isInteger(total)||total<1||total>220||!Number.isInteger(size)||size<1||size>SHARE_LIMIT)return;incomingShare={id,total,size,parts:[]};return}
 if(msg.startsWith('SHARE:CHUNK:')){let m=/^SHARE:CHUNK:([0-9a-f]{12}):(\d+):([A-Za-z0-9+/=]{1,800})$/.exec(msg);if(!m||!incomingShare||m[1]!==incomingShare.id||Number(m[2])!==incomingShare.parts.length){incomingShare=null;return}incomingShare.parts.push(m[3]);return}
 if(msg.startsWith('SHARE:END:')){let cur=incomingShare;incomingShare=null;if(!cur||msg.slice(10)!==cur.id||cur.parts.length!==cur.total)return;try{let bin=atob(cur.parts.join(''));if(bin.length!==cur.size)throw Error();let data=Uint8Array.from(bin,c=>c.charCodeAt(0));let p=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(data));validateProject(p);if(pendingShare||receiveDialog.open){notify('已有待接收的作品，請先處理。');return}pendingShare=p;$('input[name="receiveMode"][value="merge"]').checked=true;renderReceiveChoices();let count=p.blocks.blocks?.blocks?.length||0;$('#receiveSummary').textContent=`收到 ${count} 組積木、${p.buttons.length} 個遙控器按鈕。`;if(shareDialog.open)shareDialog.close();receiveDialog.showModal()}catch(e){notify('收到的作品不完整，請組員重新分享。','error')}}}
$('#receiveCancel').onclick=()=>{pendingShare=null;receiveDialog.close()};$('#receiveAccept').onclick=()=>{if(!pendingShare)return;try{let p=$('input[name="receiveMode"]:checked').value==='merge'?mergeProject(projectSnapshot(),pendingShare):pendingShare;applyProject(p,true);pendingShare=null;receiveDialog.close();notify('已接收作品；可從「連線 → 分享作品」復原。')}catch(e){console.error(e);notify(e.message?.startsWith('請')||e.message?.startsWith('新名稱')?e.message:'無法接收作品，請確認作品和瀏覽器儲存空間。','error')}};
receiveDialog.addEventListener('cancel',()=>{pendingShare=null});
